 "content": "from collections import Counter, deque

def transform(grid):
    h, w = len(grid), len(grid[0])
    counts = Counter(v for row in grid for v in row)
    wall = max(counts, key=lambda v: counts[v])  # repeated line color in the background field
    bg = max((v for v in counts if v != wall), key=lambda v: counts[v])
    seen = set()
    q = deque()
    for r in range(h):
        for c in range(w):
            if (r in (0, h-1) or c in (0, w-1)) and grid[r][c] == bg:
                seen.add((r,c)); q.append((r,c))
    while q:
        r,c = q.popleft()
        for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)):
            nr,nc = r+dr,c+dc
            if 0 <= nr < h and 0 <= nc < w and (nr,nc) not in seen and grid[nr][nc] == bg:
                seen.add((nr,nc)); q.append((nr,nc))
    out = [row[:] for row in grid]
    for r in range(h):
        for c in range(w):
            if grid[r][c] == bg and (r,c) not in seen:
                out[r][c] = 4
    return out
